/* HEXA BATTLEGROUNDS setup — PART 43 OF 83. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-memcards-20', 'cards', 'airdrop', 'Memory Cards', 'game', 1, array['any']::text[], 'Scout flips cards to find matching pairs; every matched pair shows a letter. Intel knows which symbols spell the word. Decoder knows the twist.', '{"scout":{"title":"Memory Cards","body":"Tap two cards to flip them. A matching pair stays face up and shows its letter. Call out every symbol and letter.","game":{"type":"cards","deck":[{"s":"♣","l":"D"},{"s":"♣","l":"D"},{"s":"♠","l":"X"},{"s":"★","l":"O"},{"s":"♠","l":"X"},{"s":"♦","l":"C"},{"s":"♥","l":"E"},{"s":"★","l":"O"},{"s":"♥","l":"E"},{"s":"●","l":"J"},{"s":"♦","l":"C"},{"s":"●","l":"J"}]}},"intel":{"title":"Symbol order","body":"♥   ♣   ★   ♦\n(Heart, Club, Star, Diamond)","big":true},"decoder":{"title":"The twist","body":"Read the order Intel gives you BACKWARDS (last symbol first)."}}'::jsonb, '[{"label":"4-letter word","accept":["CODE"]}]'::jsonb, false, 3, 150, 'Match all six pairs first, then let Intel read the symbols in order and the Decoder apply the twist.', '♥=E ♣=D ★=O ♦=C → Read the order Intel gives you BACKWARDS (last symbol first) → CODE', null, 25, 'published'), ('airdrop-memcards-21', 'cards', 'airdrop', 'Memory Cards', 'game', 1, array['any']::text[], 'Scout flips cards to find matching pairs; every matched pair shows a letter. Intel knows which symbols spell the word. Decoder knows the twist.', '{"scout":{"title":"Memory Cards","body":"Tap two cards to flip them. A matching pair stays face up and shows its letter. Call out every symbol and letter.","game":{"type":"cards","deck":[{"s":"●","l":"Y"},{"s":"♦","l":"T"},{"s":"●","l":"Y"},{"s":"♦","l":"T"},{"s":"★","l":"Z"},{"s":"★","l":"Z"},{"s":"♠","l":"V"},{"s":"♠","l":"V"},{"s":"♣","l":